import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

/**
 * BestieCircleTutorial
 * Handles "Step 1: Your Bestie Circle Awaits" interaction.
 * 
 * Visuals:
 * - Breathing gradient backdrop
 * - Spotlight on center
 * - "YOU" Bubble (pulsing)
 * - 5 Empty Slots (rotating dashed borders)
 * - Connection Lines (animated gradients)
 * - Floating Tooltip
 */
const BestieCircleTutorial = ({
    isActive,
    onNext,
    onComplete,
    step = 1
}) => {
    const [showTooltip, setShowTooltip] = useState(false);

    useEffect(() => {
        if (isActive) {
            // Delay tooltip appearance slightly for dramatic effect
            const timer = setTimeout(() => {
                setShowTooltip(true);
            }, 500); // 500ms delay after transition overlay starts fading
            return () => clearTimeout(timer);
        }
    }, [isActive]);

    if (!isActive) return null;

    return (
        <motion.div
            className="fixed inset-0 z-[9990] flex items-center justify-center pointer-events-auto overflow-hidden"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
        >
            {/* Living Gradient Overlay */}
            <motion.div
                className="absolute inset-0 bg-gradient-to-br from-purple-900/90 via-purple-800/90 to-pink-900/90"
                animate={{
                    background: [
                        "radial-gradient(circle at 50% 50%, rgba(88, 28, 135, 0.4) 0%, rgba(131, 24, 67, 0.8) 100%)",
                        "radial-gradient(circle at 50% 50%, rgba(107, 33, 168, 0.45) 0%, rgba(157, 23, 77, 0.85) 100%)",
                        "radial-gradient(circle at 50% 50%, rgba(88, 28, 135, 0.4) 0%, rgba(131, 24, 67, 0.8) 100%)"
                    ]
                }}
                transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
                style={{ backdropFilter: 'blur(10px)' }}
            />

            {/* The Stage */}
            <div className="relative w-full max-w-lg aspect-square flex items-center justify-center">
                {/* Glow Layers */}
                <motion.div
                    className="absolute inset-20 rounded-full bg-white/5 blur-3xl"
                    animate={{ scale: [1, 1.05, 1], opacity: [0.3, 0.4, 0.3] }}
                    transition={{ duration: 2.5, repeat: Infinity, ease: "easeInOut" }}
                />
                <motion.div
                    className="absolute inset-10 rounded-full bg-pink-500/10 blur-2xl"
                    animate={{ scale: [1, 1.02, 1], opacity: [0.2, 0.3, 0.2] }}
                    transition={{ duration: 2.5, repeat: Infinity, ease: "easeInOut", delay: 0.2 }}
                />

                {/* Center: YOU Bubble */}
                <YouBubble />

                {/* Empty Slots & Connection Lines */}
                <SlotsAndConnections />
            </div>

            {/* Tooltip */}
            <AnimatePresence>
                {showTooltip && (
                    <Tooltip
                        step={step}
                        onNext={onNext}
                    />
                )}
            </AnimatePresence>


        </motion.div>
    );
};

const YouBubble = () => {
    return (
        <motion.div
            className="relative z-20 w-24 h-24 rounded-full flex items-center justify-center shadow-lg"
            style={{
                background: 'linear-gradient(135deg, #A855F7 0%, #EC4899 100%)',
                boxShadow: '0 10px 25px -5px rgba(236, 72, 153, 0.4), inset 0 2px 4px 0 rgba(255, 255, 255, 0.3)'
            }}
            animate={{ scale: [1, 1.05, 1] }}
            transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
        >
            <div className="absolute inset-0 rounded-full bg-white/10 blur-[1px]" />
            <span className="text-white font-bold text-xl tracking-widest drop-shadow-md">YOU</span>

            {/* Catch-light */}
            <div className="absolute top-4 left-4 w-3 h-2 bg-white/40 rounded-full rotate-[-45deg] blur-[1px]" />
        </motion.div>
    );
};

const SlotsAndConnections = () => {
    // 5 slots in pentagon arrangement
    const slots = Array.from({ length: 5 }).map((_, i) => {
        const angle = (i * 72 - 90) * (Math.PI / 180); // Start at 12 o'clock (-90 deg)
        const radius = 100; // Distance from center
        const x = Math.cos(angle) * radius; // React handles percent based on center being 0,0? No, standard DOM.
        // CSS translate is easier: translate(x px, y px)
        return { x: Math.cos(angle) * 140, y: Math.sin(angle) * 140, id: i };
    });

    return (
        <>
            {slots.map((slot, i) => (
                <React.Fragment key={slot.id}>
                    {/* Connection Line */}
                    <ConnectionLine x={slot.x} y={slot.y} delay={i * 0.5} />

                    {/* Empty Slot */}
                    <EmptySlot x={slot.x} y={slot.y} />
                </React.Fragment>
            ))}
        </>
    );
};

const EmptySlot = ({ x, y }) => {
    return (
        <motion.div
            className="absolute w-16 h-16 rounded-full border-2 border-dashed border-white/40 flex items-center justify-center"
            style={{ x, y }}
            animate={{
                rotate: 360,
                borderColor: ['rgba(255,255,255,0.4)', 'rgba(255,255,255,0.6)', 'rgba(255,255,255,0.4)']
            }}
            transition={{
                rotate: { duration: 20, repeat: Infinity, ease: "linear" },
                borderColor: { duration: 3, repeat: Infinity, ease: "easeInOut" }
            }}
        >
            <motion.span
                className="text-white/50 text-2xl font-light"
                animate={{ scale: [1, 1.1, 1] }}
                transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
            >
                +
            </motion.span>
        </motion.div>
    );
};

const ConnectionLine = ({ x, y, delay }) => {
    // Calculate angle to rotate the line
    const angle = Math.atan2(y, x) * (180 / Math.PI);
    const length = Math.sqrt(x * x + y * y) - 60; // Subtract radius of bubbles approx

    return (
        <div
            className="absolute top-1/2 left-1/2 h-[2px] origin-left bg-white/20"
            style={{
                width: length,
                transform: `rotate(${angle}deg) translate(48px, 0)` // Start from edge of YOU bubble (approx 48px radio)
            }}
        >
            <motion.div
                className="absolute inset-0 bg-gradient-to-r from-transparent via-pink-400 to-transparent"
                initial={{ x: '-100%' }}
                animate={{ x: '100%' }}
                transition={{
                    duration: 2.5,
                    repeat: Infinity,
                    ease: "linear",
                    delay: delay
                }}
                style={{ width: '40%' }} // Pulse length
            />
        </div>
    );
};

const Tooltip = ({ onNext }) => {
    return (
        <motion.div
            className="absolute w-11/12 max-w-sm bg-white/95 backdrop-blur-md rounded-[24px] p-6 shadow-2xl z-30 flex flex-col items-center text-center border border-pink-100/50"
            initial={{ y: 20, opacity: 0, scale: 0.9 }}
            animate={{ y: -220, opacity: 1, scale: 1 }} // Float above
            exit={{ y: 0, opacity: 0, scale: 0.9 }}
            transition={{
                type: "spring",
                damping: 20,
                stiffness: 300,
                delay: 0.2 // Wait for bubble to establish
            }}
        >
            {/* Floating Emoji */}
            <motion.div
                className="text-4xl mb-4"
                animate={{ y: [-2, 2, -2] }}
                transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
            >
                💜
            </motion.div>

            <h3 className="text-xl font-bold bg-gradient-to-r from-purple-600 to-pink-600 bg-clip-text text-transparent mb-3">
                Your Bestie Circle Awaits ✨
            </h3>

            <p className="text-gray-600 leading-relaxed mb-6 text-sm">
                You just took care of yourself with a check-in. Now let's connect you to the people who have your back. Your circle is where your chosen family shows up when it matters most.
            </p>

            {/* Progress Dots */}
            <div className="flex gap-2 mb-6">
                <motion.div className="w-2.5 h-2.5 rounded-full bg-gradient-to-r from-purple-500 to-pink-500 shadow-sm" animate={{ scale: [1, 1.2, 1] }} transition={{ duration: 2, repeat: Infinity }} />
                <div className="w-2.5 h-2.5 rounded-full bg-gray-200" />
                <div className="w-2.5 h-2.5 rounded-full bg-gray-200" />
                <div className="w-2.5 h-2.5 rounded-full bg-gray-200" />
                <div className="w-2.5 h-2.5 rounded-full bg-gray-200" />
            </div>

            {/* Button */}
            <button
                onClick={onNext}
                className="w-full py-4 rounded-xl bg-gradient-to-r from-pink-500 to-purple-600 text-white font-bold text-lg shadow-lg relative overflow-hidden group"
            >
                <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000" />
                Let's Go!
            </button>

        </motion.div>
    );
};

export default BestieCircleTutorial;
